#include <WiFi.h>
#include <WebServer.h>
#include <Update.h>

const char* ssid = "LOW-SPEC";
const char* password = "lowspec32";

WebServer server(80);

const char INDEX_HTML[] PROGMEM = R"rawliteral(
<!DOCTYPE html>
<html>
<head>
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>LOW-SPEC</title>
<style>
body {
  background:#111;
  color:#eee;
  font-family:Arial,sans-serif;
  margin:30px;
}
h1 { color:#ddd; }
.card {
  border:1px solid #555;
  border-radius:10px;
  padding:20px;
  max-width:500px;
}
button,input {
  font-size:18px;
  padding:10px;
  margin-top:10px;
}
</style>
</head>
<body>
<div class="card">
<h1>LOW-SPEC TOOL</h1>
<p>ESP32: ONLINE</p>
<p>Wi-Fi: LOW-SPEC</p>
<p>IP: 192.168.4.1</p>

<h2>Firmware Update</h2>
<form method="POST" action="/update"
      enctype="multipart/form-data">
<input type="file" name="update">
<br>
<input type="submit" value="Upload Firmware">
</form>
</div>
</body>
</html>
)rawliteral";

void setup() {
  Serial.begin(115200);

  WiFi.mode(WIFI_AP);
  WiFi.softAP(ssid, password);

  Serial.println();
  Serial.println("LOW-SPEC ONLINE");
  Serial.print("IP: ");
  Serial.println(WiFi.softAPIP());

  server.on("/", HTTP_GET, []() {
    server.send(200, "text/html", INDEX_HTML);
  });

  server.on(
    "/update",
    HTTP_POST,
    []() {
      server.send(
        200,
        "text/plain",
        Update.hasError()
          ? "UPDATE FAILED"
          : "UPDATE SUCCESS - REBOOTING"
      );

      delay(1000);
      ESP.restart();
    },
    []() {
      HTTPUpload& upload = server.upload();

      if (upload.status == UPLOAD_FILE_START) {
        Update.begin(UPDATE_SIZE_UNKNOWN);
      }
      else if (upload.status == UPLOAD_FILE_WRITE) {
        Update.write(upload.buf, upload.currentSize);
      }
      else if (upload.status == UPLOAD_FILE_END) {
        Update.end(true);
      }
    }
  );

  server.begin();
}

void loop() {
  server.handleClient();
}
